import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Database real-driver testing — 16 axis × 3 provider = 48 row grid + testcontainers pattern (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/database-real-driver-testing.md","filePath":"concepts/database-real-driver-testing.md"}'),d={name:"concepts/database-real-driver-testing.md"};function c(s,e,r,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="database-real-driver-testing-—-16-axis-×-3-provider-48-row-grid-testcontainers-pattern-ssot" tabindex="-1">Database real-driver testing — 16 axis × 3 provider = 48 row grid + testcontainers pattern (SSOT) <a class="header-anchor" href="#database-real-driver-testing-—-16-axis-×-3-provider-48-row-grid-testcontainers-pattern-ssot" aria-label="Permalink to &quot;Database real-driver testing — 16 axis × 3 provider = 48 row grid + testcontainers pattern (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.26 orm work covered the <strong>8 base semantics</strong> (replication / CDC / logical replication / MVCC / RLS / connection pool / partitioning / vector store) as unified mocks for Postgres + MySQL + SQLite — the <code>docs/concepts/db-advanced-testing.md</code> doc is the SSOT for those 8 axes. v1.32 adds <strong>8 advanced axes on top of that base</strong> — the ones production teams hit once their mock-only suite is green but real database behavior (logical streaming re-reads, cluster certification conflicts, WAL checkpoint pauses, FTS5 tokenizer stopword surprises) starts showing up in incident reports. This concept doc is the SSOT for those 8 axes; the tutorials (61-63) and dogfood apps (v1.32-2/3/4) are the concrete implementations.</p><h2 id="the-16-axis-grid" tabindex="-1">The 16-axis grid <a class="header-anchor" href="#the-16-axis-grid" aria-label="Permalink to &quot;The 16-axis grid&quot;">​</a></h2><p>The 8 base axes (v0.9) + 8 advanced axes (v0.10) form a 16-axis grid. The base axes cover &quot;does replication happen at all&quot;; the advanced axes cover &quot;how does replication break under real load&quot;.</p><table tabindex="0"><thead><tr><th>#</th><th>Axis</th><th>Real-world failure it catches</th><th>v0.10 API</th></tr></thead><tbody><tr><td>1</td><td><code>replication</code></td><td>The replica fell behind and never caught up</td><td><code>createReplicationSession</code> (v0.9)</td></tr><tr><td>2</td><td><code>cdc</code></td><td>The outbox event was decoded twice</td><td><code>createCdcSession</code> (v0.9)</td></tr><tr><td>3</td><td><code>logical-replication</code></td><td>The publication + subscription pair went out of sync</td><td><code>createLogicalRepSession</code> (v0.9)</td></tr><tr><td>4</td><td><code>mvcc</code></td><td>A serializable transaction aborted spuriously</td><td><code>createMvccSession</code> (v0.9)</td></tr><tr><td>5</td><td><code>rls</code></td><td>The tenant filter did not apply to a bypass role</td><td><code>createRlsSession</code> (v0.9)</td></tr><tr><td>6</td><td><code>connection-pool</code></td><td>The pool exhausted under a burst and refused connections</td><td><code>createPoolSession</code> (v0.9)</td></tr><tr><td>7</td><td><code>partitioning</code></td><td>The partition pruner picked the wrong partition</td><td><code>createPartitioningSession</code> (v0.9)</td></tr><tr><td>8</td><td><code>vector-store</code></td><td>The HNSW index returned stale results after a bulk insert</td><td><code>createVectorStoreSession</code> (v0.9)</td></tr><tr><td>9</td><td><code>logical-replication-advanced</code></td><td>The subscriber restarted and re-read 40 MB of WAL</td><td><code>createLogicalReplicationAdvancedSession</code></td></tr><tr><td>10</td><td><code>mvcc-advanced</code></td><td>XID wraparound warning fired at 200M without freeze running</td><td><code>createMvccAdvancedSession</code></td></tr><tr><td>11</td><td><code>mysql-cluster</code></td><td>The write got certified on 2 nodes but rejected on the 3rd</td><td><code>createMysqlClusterSession</code></td></tr><tr><td>12</td><td><code>binlog</code></td><td>A GTID gap accumulated after a mixed-format binlog run</td><td><code>createBinlogSession</code></td></tr><tr><td>13</td><td><code>sqlite-wal</code></td><td>The WAL file kept growing until the mount ran out of space</td><td><code>createSqliteWalSession</code></td></tr><tr><td>14</td><td><code>fts5</code></td><td>The porter tokenizer silently dropped a search term as a stopword</td><td><code>createFts5Session</code></td></tr><tr><td>15</td><td><code>txn-isolation</code></td><td>A phantom read leaked through a read-committed transaction</td><td><code>createTxnIsolationSession</code></td></tr><tr><td>16</td><td><code>pool-advanced</code></td><td>The pool drain finished but 3 connections were still active</td><td><code>createPoolAdvancedSession</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + backend env, testcontainers, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 61 covers axis 9 in depth, tutorial 62 covers axis 11, tutorial 63 covers axes 13 + 14.</p><h2 id="the-3-provider-×-3-backend-×-16-axis-144-cell-fidelity-grid" tabindex="-1">The 3-provider × 3-backend × 16-axis = 144 cell fidelity grid <a class="header-anchor" href="#the-3-provider-×-3-backend-×-16-axis-144-cell-fidelity-grid" aria-label="Permalink to &quot;The 3-provider × 3-backend × 16-axis = 144 cell fidelity grid&quot;">​</a></h2><p>Every axis emits both a <code>neutralEvent</code> (provider-neutral name) and a <code>backendEvent</code> (backend-specific dialect). The <code>collectFidelityCoverage()</code> helper walks the 144-row grid (3 provider × 3 backend × 16 axis) and returns the full mapping. This is the data structure downstream release-gate checks read to assert &quot;every axis has a dialect entry&quot;.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { collectFidelityCoverage } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@kiwa-test/orm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> coverage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> collectFidelityCoverage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  providers: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;drizzle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;prisma&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;kysely&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  backends: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;postgres&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mysql&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sqlite&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(coverage.rows.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 144</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(coverage.axes.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 16</span></span></code></pre></div><p>Not every dialect entry lands on every backend — server-only axes (streaming replication, CDC, group replication) have no SQLite analogue and fall back to the neutral name via <code>backendEventName()</code>. This is by design — a test iterating the grid can assert on the neutral name for portability and on the backend-specific dialect for backend-native telemetry.</p><h2 id="real-driver-env-gate-contract" tabindex="-1">Real-driver env-gate contract <a class="header-anchor" href="#real-driver-env-gate-contract" aria-label="Permalink to &quot;Real-driver env-gate contract&quot;">​</a></h2><p><code>KIWA_MODE=real</code> flips on the real-driver assertions. The required env per backend.</p><ul><li><strong>Postgres</strong> axes (<code>logical-replication-advanced</code> / <code>mvcc-advanced</code>) → <code>POSTGRES_KEY</code></li><li><strong>MySQL</strong> axes (<code>mysql-cluster</code> / <code>binlog</code>) → <code>MYSQL_KEY</code></li><li><strong>SQLite</strong> axes (<code>sqlite-wal</code> / <code>fts5</code>) → <code>SQLITE_KEY</code></li><li><strong>Cross-backend</strong> axes (<code>txn-isolation</code> / <code>pool-advanced</code>) → any of the 3 keys (matches the backend under test)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when both <code>KIWA_MODE=real</code> and the required key are present. That means CI stays cheap by default (mock only), the nightly job flips both envs (real driver + testcontainers), and the fidelity harness ties the two together.</p><h2 id="the-testcontainers-pattern" tabindex="-1">The testcontainers pattern <a class="header-anchor" href="#the-testcontainers-pattern" aria-label="Permalink to &quot;The testcontainers pattern&quot;">​</a></h2><p>The 3 dogfood app v2 upgrades (v1.32-2 / v1.32-3 / v1.32-4) each expose a <code>pnpm test:real</code> command that flips <code>KIWA_MODE=real</code> and spins up the backend under testcontainers.</p><ul><li><code>examples/dogfood-postgres-cdc-outbox-app</code> v2 — Postgres 16 + logical replication (publication + subscription + slot + <code>wal_level = logical</code>) + pgvector + <code>pg_replication_origin_progress</code> telemetry + Playwright e2e that walks the <code>startLogicalStreaming</code> → <code>trackReplicationOrigin</code> → <code>confirmTwoSafeCommit</code> → <code>syncCascadedSubscription</code> state machine against the real broker.</li><li><code>examples/dogfood-mysql-rls-tenant-app</code> v2 — MySQL 8 + group replication (single-primary + member weight + certification + <code>performance_schema.replication_group_member_stats.COUNT_CONFLICTS_DETECTED</code>) + Router R/W split + <code>INFORMATION_SCHEMA.INNODB_TRX</code> telemetry + Playwright e2e that walks the <code>joinClusterMember</code> → <code>electClusterPrimary</code> → <code>detectClusterConflict</code> → <code>leaveClusterMember</code> state machine against the real cluster.</li><li><code>examples/dogfood-sqlite-wal-fts-app</code> — libsql / SQLite testcontainer + WAL mode (<code>PRAGMA journal_mode = WAL</code>) + FTS5 virtual table (<code>unicode61</code> / <code>porter</code> / <code>trigram</code> tokenizers) + Bun edge runtime + Playwright e2e that walks the <code>switchJournalMode</code> → <code>crossWalSizeThreshold</code> → <code>triggerWalCheckpoint</code> → <code>mapSharedMemory</code> state machine and the <code>createFts5VirtualTable</code> → <code>tokenizeFts5Document</code> → <code>matchFts5Query</code> → <code>inspectFts5Vocab</code> state machine against the real DB file.</li></ul><p>The pattern each v2 app follows.</p><ol><li>Keep the v1 mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:real</code> command that requires the backend env (<code>POSTGRES_KEY</code> / <code>MYSQL_KEY</code> / <code>SQLITE_KEY</code>) and pulls the testcontainers image.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real behavior&quot; — the mock gets the fix.</li><li>Route the e2e through Playwright when the flow crosses UI boundaries (e.g., the tenant admin UI in the RLS app or the vector search UI in the WAL+FTS app).</li></ol><h2 id="what-each-of-the-8-advanced-axes-catches" tabindex="-1">What each of the 8 advanced axes catches <a class="header-anchor" href="#what-each-of-the-8-advanced-axes-catches" aria-label="Permalink to &quot;What each of the 8 advanced axes catches&quot;">​</a></h2><h3 id="_9-logical-replication-advanced-—-pgoutput-origin-two-safe-cascade" tabindex="-1">9. <code>logical-replication-advanced</code> — pgoutput + origin + two-safe + cascade <a class="header-anchor" href="#_9-logical-replication-advanced-—-pgoutput-origin-two-safe-cascade" aria-label="Permalink to &quot;9. `logical-replication-advanced` — pgoutput + origin + two-safe + cascade&quot;">​</a></h3><p>The <code>LogicalReplicationAdvancedState</code> state machine (<code>idle</code> → <code>streaming</code> → <code>origin-tracked</code> → <code>two-safe-confirmed</code> → <code>cascade-synced</code>) covers 4 real Postgres primitives — <code>START_REPLICATION</code> protocol handshake, <code>pg_replication_origin_advance</code> progress tracking, <code>synchronous_commit = remote_apply</code> two-safe confirmation, cascaded subscription topology. The classic bug caught is &quot;the subscriber restarted and re-read 40 MB of WAL&quot; — persisting <code>confirmed_flush_lsn</code> on shutdown and passing it as <code>startLsn</code> on restart is what makes recovery cheap, and the mock enforces <code>startLsn &gt; 0</code>.</p><h3 id="_10-mvcc-advanced-—-tuple-visibility-bloat-hot-chains-xid-wraparound" tabindex="-1">10. <code>mvcc-advanced</code> — tuple visibility + bloat + HOT chains + XID wraparound <a class="header-anchor" href="#_10-mvcc-advanced-—-tuple-visibility-bloat-hot-chains-xid-wraparound" aria-label="Permalink to &quot;10. `mvcc-advanced` — tuple visibility + bloat + HOT chains + XID wraparound&quot;">​</a></h3><p>The <code>MvccAdvancedState</code> state machine (<code>idle</code> → <code>visibility-checked</code> → <code>bloat-measured</code> → <code>hot-updated</code> → <code>xid-wraparound-detected</code>) covers 4 Postgres MVCC internals — heap tuple <code>xmin</code> / <code>xmax</code> visibility against a snapshot, <code>pg_stat_user_tables.n_dead_tup / n_live_tup</code> bloat measurement, HOT (Heap Only Tuple) update chain length, XID wraparound warning threshold. The classic bug caught is &quot;vacuum did not run for 2 weeks and the XID age hit 200M&quot; — the mock takes <code>warningAge</code> as a parameter so tests can assert on wraparound detection deterministically.</p><h3 id="_11-mysql-cluster-—-group-replication-membership-election-conflict-leave" tabindex="-1">11. <code>mysql-cluster</code> — group replication membership + election + conflict + leave <a class="header-anchor" href="#_11-mysql-cluster-—-group-replication-membership-election-conflict-leave" aria-label="Permalink to &quot;11. `mysql-cluster` — group replication membership + election + conflict + leave&quot;">​</a></h3><p>The <code>MysqlClusterState</code> state machine (<code>empty</code> → <code>joined</code> → <code>primary-elected</code> → <code>conflict-detected</code> → <code>member-left</code>) covers 4 MySQL 8 group replication primitives — <code>START GROUP_REPLICATION</code> with <code>group_replication_member_weight</code>, single-primary election among joined members, certification conflict on overlapping writes, <code>STOP GROUP_REPLICATION</code> shrinking the group. The classic bug caught is &quot;the write got certified on 2 nodes but rejected on the 3rd&quot; — the mock&#39;s <code>detectClusterConflict</code> increments <code>conflictCount</code> on every conflict, letting a test assert on certification rate regressions.</p><h3 id="_12-binlog-—-position-gtid-format-gap" tabindex="-1">12. <code>binlog</code> — position + GTID + format + gap <a class="header-anchor" href="#_12-binlog-—-position-gtid-format-gap" aria-label="Permalink to &quot;12. `binlog` — position + GTID + format + gap&quot;">​</a></h3><p>The <code>BinlogState</code> state machine (<code>idle</code> → <code>positioned</code> → <code>gtid-updated</code> → <code>format-negotiated</code> → <code>gap-detected</code>) covers 4 MySQL binlog primitives — <code>SHOW MASTER STATUS</code> file+position, GTID set maintenance (<code>gtid_executed</code>), <code>binlog_format = ROW / STATEMENT / MIXED</code> negotiation, GTID gap detection (a missing GTID in the executed set). The classic bug caught is &quot;a mixed-format binlog run created a GTID gap&quot; — the mock&#39;s <code>updateGtidSet</code> rejects duplicate GTIDs and the <code>detectGtidGap</code> requires the expected GTID to be absent, letting a test assert on gap detection deterministically.</p><h3 id="_13-sqlite-wal-—-journal-mode-threshold-checkpoint-shared-memory" tabindex="-1">13. <code>sqlite-wal</code> — journal_mode + threshold + checkpoint + shared memory <a class="header-anchor" href="#_13-sqlite-wal-—-journal-mode-threshold-checkpoint-shared-memory" aria-label="Permalink to &quot;13. `sqlite-wal` — journal_mode + threshold + checkpoint + shared memory&quot;">​</a></h3><p>The <code>SqliteWalState</code> state machine (<code>rollback-journal</code> → <code>wal-enabled</code> → <code>threshold-crossed</code> → <code>checkpointed</code> → <code>shared-memory-mapped</code>) covers 4 SQLite WAL primitives — <code>PRAGMA journal_mode = WAL</code> switch, <code>wal_autocheckpoint</code> size threshold, <code>PRAGMA wal_checkpoint(TRUNCATE)</code> copy+truncate, <code>-shm</code> wal-index memory mapping. The classic bug caught is &quot;the WAL file kept growing until the mount ran out of space&quot; — the mock&#39;s <code>crossWalSizeThreshold</code> requires <code>walSizeBytes &gt; thresholdBytes</code> so a test that claims a threshold cross with equal sizes is a bug.</p><h3 id="_14-fts5-—-virtual-table-tokenizer-match-vocab" tabindex="-1">14. <code>fts5</code> — virtual table + tokenizer + MATCH + vocab <a class="header-anchor" href="#_14-fts5-—-virtual-table-tokenizer-match-vocab" aria-label="Permalink to &quot;14. `fts5` — virtual table + tokenizer + MATCH + vocab&quot;">​</a></h3><p>The <code>Fts5State</code> state machine (<code>empty</code> → <code>virtual-table-created</code> → <code>tokenized</code> → <code>matched</code> → <code>vocab-inspected</code>) covers 4 SQLite FTS5 primitives — <code>CREATE VIRTUAL TABLE ... USING fts5(...)</code>, tokenizer choice (<code>unicode61</code> / <code>porter</code> / <code>trigram</code>), <code>MATCH</code> queries with BM25 rank, <code>fts5vocab</code> term inspection. The classic bug caught is &quot;the porter tokenizer silently dropped a search term as a stopword&quot; — the mock&#39;s <code>inspectFts5Vocab</code> requires <code>occurrences &gt;= 0</code>, letting a test assert on stopword drops via <code>occurrences === 0</code>.</p><h3 id="_15-txn-isolation-—-level-dirty-read-non-repeatable-phantom" tabindex="-1">15. <code>txn-isolation</code> — level + dirty read + non-repeatable + phantom <a class="header-anchor" href="#_15-txn-isolation-—-level-dirty-read-non-repeatable-phantom" aria-label="Permalink to &quot;15. `txn-isolation` — level + dirty read + non-repeatable + phantom&quot;">​</a></h3><p>The <code>TxnIsolationState</code> state machine (<code>idle</code> → <code>level-set</code> → <code>dirty-read-blocked</code> → <code>non-repeatable-read-blocked</code> → <code>phantom-read-blocked</code>) covers the 4 SQL isolation levels (<code>READ UNCOMMITTED</code> → <code>READ COMMITTED</code> → <code>REPEATABLE READ</code> → <code>SERIALIZABLE</code>) and the 3 ANSI phenomena they block. The mock enforces the containment — <code>blockPhantomRead</code> requires <code>blockNonRepeatableRead</code> to have run, <code>blockNonRepeatableRead</code> requires <code>blockDirtyRead</code>, and only <code>serializable</code> blocks phantoms. The classic bug caught is &quot;a phantom read leaked through a read-committed transaction&quot; — a test that asserts on <code>blockPhantomRead</code> under <code>read-committed</code> fails with the exact error message the mock emits.</p><h3 id="_16-pool-advanced-—-health-check-warmup-drain-metrics" tabindex="-1">16. <code>pool-advanced</code> — health check + warmup + drain + metrics <a class="header-anchor" href="#_16-pool-advanced-—-health-check-warmup-drain-metrics" aria-label="Permalink to &quot;16. `pool-advanced` — health check + warmup + drain + metrics&quot;">​</a></h3><p>The <code>PoolAdvancedState</code> state machine (<code>cold</code> → <code>healthy</code> → <code>warmed-up</code> → <code>draining</code> → <code>metrics-exported</code>) covers 4 connection pool primitives — health check (PgBouncer <code>server_check</code> / ProxySQL <code>mysql-monitor_ping_interval_server_max</code>), warm-up (<code>minWarmConnections</code>), graceful drain (<code>deadlineMs</code> before force-close), metrics export (<code>active</code> / <code>idle</code> / <code>waiting</code> counts). The classic bug caught is &quot;the pool drain finished but 3 connections were still active&quot; — the mock&#39;s <code>drainPoolGracefully</code> resets <code>activeConnections</code> to 0 and the <code>exportPoolMetrics</code> requires non-negative counters.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.32 does not add a 14th release-gate axis. The 8 advanced axes gate the orm package&#39;s own tests (via <code>pnpm --filter @kiwa-test/orm test</code>) but do not surface as a per-package <code>@kiwa-test/quality-metrics</code> axis. The reasoning — the fidelity harness is backend-shape-specific, and a package that does not use a database has nothing to assert on. When a future milestone adds a <code>backend.fidelity</code> axis that describes &quot;which backends this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.32 keeps the axis count at 13.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 8 base semantics (replication / CDC / logical replication / MVCC / RLS / connection pool / partitioning / vector store) live in <code>docs/concepts/db-advanced-testing.md</code>. v1.32 does not modify that doc.</li><li>The 8 advanced axes live in this doc. Tutorials 61-63 and the migration guide (v1.31 → v1.32) link back here for the axis SSOT.</li><li>The 3-provider × 3-backend × 16-axis grid is the harness&#39;s data structure. The <code>collectFidelityCoverage()</code> implementation in <code>packages/orm/src/semantics/fidelity.ts</code> is the code SSOT — this doc&#39;s grid table is derived from that code.</li><li>The <code>KIWA_MODE=real</code> env-gate contract is shared with the v1.22 real-driver testing tutorial (auth adapters + Keycloak) and the v1.31 streaming real-driver concept doc. All three use the same pattern; the database axes just add backend-specific <code>_KEY</code> envs.</li></ul>',40)])])}const g=t(d,[["render",c]]);export{u as __pageData,g as default};
